// src/channel/protocol.ts
import { randomBytes } from "node:crypto";
import { tmpdir } from "node:os";
import { join as join2 } from "node:path";
var NETA_SOCKET_ENV = "NETA_SOCKET";
var NETA_WORKER_ENV = "NETA_WORKER_ID";
var NETA_WORKER_TOKEN_ENV = "NETA_WORKER_TOKEN";
var NETA_SCRATCH_ENV = "NETA_SCRATCH";
var NETA_LEADER_ENV = "NETA_LEADER_TOKEN";
var LEADER_REQUEST_TYPES = new Set([
  "spawn",
  "workers",
  "status",
  "log",
  "tail",
  "room-tail",
  "wait",
  "send",
  "answer",
  "kill"
]);
function createChannelAddress() {
  const id = `${process.pid}-${randomBytes(4).toString("hex")}`;
  if (process.platform === "win32")
    return `\\\\.\\pipe\\neta-${id}`;
  return join2(tmpdir(), `neta-${id}.sock`);
}

// src/channel/client.ts
var CHANNEL_COMMANDS = new Set(["progress", "ask", "say", "room", "status"]);
var CHANNEL_HELP = `Worker channel commands (available inside a Neta worker):

  ${APP_NAME} progress <message> Records a progress milestone in your log. Use it when you start, when a major step completes, and when something surprising changes your plan — one line each, not a running commentary. The leader and the user read these at a glance; frequent trivial calls bury the signal.
  ${APP_NAME} ask <question>     Ask the leader and wait for the answer. Not available to journeyman workers.
  ${APP_NAME} say <message>      Post to your room, visible to the other members.
  ${APP_NAME} room [--tail N]    Read your room transcript.
  ${APP_NAME} status --writers   Show active, queued and finished writers.
`;
function sendChannelRequest(address, request) {
  return new Promise((resolve, reject) => {
    const socket = connect(address);
    let buffer = "";
    let settled = false;
    const finish = (response) => {
      if (settled)
        return;
      settled = true;
      socket.end();
      resolve(response);
    };
    socket.on("connect", () => {
      socket.write(`${JSON.stringify(request)}
`);
    });
    socket.on("data", (chunk) => {
      buffer += chunk.toString();
      const newline = buffer.indexOf(`
`);
      if (newline === -1)
        return;
      const line = buffer.slice(0, newline);
      try {
        finish(JSON.parse(line));
      } catch (error) {
        finish({ ok: false, error: `Malformed response from leader: ${error}` });
      }
    });
    socket.on("error", (error) => {
      if (settled)
        return;
      settled = true;
      reject(error);
    });
    socket.on("close", () => {
      if (settled)
        return;
      settled = true;
      resolve({ ok: false, error: "Leader closed the channel without answering." });
    });
  });
}
function parseTail(args) {
  const index = args.indexOf("--tail");
  if (index === -1)
    return;
  const value = Number.parseInt(args[index + 1] ?? "", 10);
  return Number.isFinite(value) ? value : undefined;
}
async function handleWorkerChannelCommand(args) {
  const address = process.env[NETA_SOCKET_ENV];
  const workerId = process.env[NETA_WORKER_ENV];
  const token = process.env[NETA_WORKER_TOKEN_ENV];
  const command = args[0];
  if (!address || !workerId || !command || !CHANNEL_COMMANDS.has(command))
    return false;
  if (!token) {
    console.error("Worker channel token is missing.");
    process.exitCode = 1;
    return true;
  }
  const rest = args.slice(1);
  if (rest.includes("--help") || rest.includes("-h")) {
    console.log(CHANNEL_HELP);
    return true;
  }
  let request;
  if (command === "room") {
    request = { type: "room", workerId, token, tail: parseTail(rest) };
  } else if (command === "status") {
    if (rest.length !== 1 || rest[0] !== "--writers") {
      console.error(`Usage: ${APP_NAME} status --writers`);
      process.exitCode = 1;
      return true;
    }
    request = { type: "writer-status", workerId, token };
  } else {
    const text = rest.join(" ").trim();
    if (!text) {
      console.error(`Usage: ${APP_NAME} ${command} <text>`);
      process.exitCode = 1;
      return true;
    }
    request = { type: command, workerId, token, text };
  }
  try {
    const response = await sendChannelRequest(address, request);
    if (response.ok) {
      if (response.text)
        console.log(response.text);
      else if (command === "progress" || command === "say")
        console.log("ok");
    } else {
      console.error(response.error);
      process.exitCode = 1;
    }
  } catch (error) {
    console.error(`Could not reach the leader on ${address}: ${error instanceof Error ? error.message : error}`);
    process.exitCode = 1;
  }
  return true;
}

