async function listBackendModels(backendName, cwd) {
  const config2 = loadConfig(cwd);
  const names = backendName ? [backendName] : config2.backendNames();
  for (const name of names) {
    const backend = config2.launcher(name);
    if (!backend.command) {
      console.log(`${name}: no command configured.`);
      continue;
    }
    const connection = new AcpConnection({
      command: backend.command,
      args: backend.args,
      cwd,
      env: backend.env,
      allowMutations: false,
      onUpdate: () => {},
      onStderr: () => {},
      onDenied: () => {}
    });
    try {
      await connection.start();
      const { currentModel, modes, currentMode, thoughtLevels, currentThoughtLevel } = connection.offered;
      const models = selectableBackendModels(config2.isClaudeBackend(name), connection.offered.models);
      console.log(`
${name}`);
      console.log(`  models: ${models.length === 0 ? "(none advertised)" : ""}`);
      for (const model of models)
        console.log(`    ${model}${model === currentModel ? "  (default)" : ""}`);
      console.log(`  modes: ${modes.map((mode) => mode === currentMode ? `${mode} (default)` : mode).join(", ")}`);
      if (thoughtLevels.length > 0) {
        console.log(`  thought levels: ${thoughtLevels.map((level) => level === currentThoughtLevel ? `${level} (default)` : level).join(", ")}`);
      }
      const mapped = TIERS.filter((tier2) => {
        const tierConfig = config2.tierMapping()[tier2];
        return tierConfig?.backend === name;
      }).map((tier2) => `${tier2}=${config2.resolve(tier2, name).model ?? "backend default"}`).join(", ");
      if (mapped)
        console.log(`  your tiers: ${mapped}`);
    } catch (error51) {
      console.log(`
${name}
  could not start: ${error51 instanceof Error ? error51.message : String(error51)}`);
    } finally {
      await connection.kill();
    }
  }
  return 0;
}
function selectableBackendModels(claudeLineage, models) {
  return claudeLineage ? models.filter((model) => !isForbiddenClaudeModel(model)) : [...models];
}

